    summary:
      'What the federal cybersecurity agency provides to utilities without charge: the performance goals, regional advisors, external vulnerability scanning, control system advisories, the exploited catalog, a self-assessment tool, exercises, and incident reporting.',
    answer:
      'The federal cybersecurity agency offers water and wastewater utilities a set of free services and publications: the cross-sector cybersecurity performance goals, a prioritized list of controls with cost and impact ratings, and the water and wastewater sector goals that map them to utility systems; regional cybersecurity advisors who visit, assess, and connect utilities to services; a vulnerability scanning service that continuously scans a utility internet-facing addresses and reports what an attacker would see; the industrial control systems advisories and the catalog of vulnerabilities known to be exploited; a self-assessment tool with a module for the water sector; tabletop exercise packages with water scenarios; guidance on ransomware; a water sector toolkit that collects the sector material in one place; and a channel for reporting incidents and receiving assistance. A utility of any size starts with the advisor and the scanning service, works the performance goals, and uses the exercise package once a year.',
    keyPoints: [
      'The performance goals are the prioritized to-do list; the water sector goals translate them into utility terms.',
      'Regional advisors visit, assess, and connect; they are the human entry point to everything else.',
      'The external scanning service shows what the internet sees of the utility, weekly, for free.',
      'The industrial control advisories and the exploited catalog are the vulnerability feeds.',
      'The self-assessment tool and the exercise packages are the annual review and the annual drill.',
      'Incidents are reported to the agency, which also assists; the number is on the plan.',
    ],
